describe('the websocket frame validator', () => {
  it('accepts list_sessions and validates its limit and before cursor', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });

    expect(validateMessage({type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'}},
    });

    expect(validateMessage({type: 'list_sessions', userId: 'other'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });

    expect(validateMessage({type: 'list_sessions', limit: 'ten'})).toEqual({
      valid: false,
      error: 'limit must be a non-negative integer',
    });

    expect(validateMessage({type: 'list_sessions', limit: -1})).toEqual({
      valid: false,
      error: 'limit must be a non-negative integer',
    });

    expect(validateMessage({type: 'list_sessions', limit: 1.5})).toEqual({
      valid: false,
      error: 'limit must be a non-negative integer',
    });

    expect(validateMessage({type: 'list_sessions', before: 'not-an-object'})).toEqual({
      valid: false,
      error: 'before must be a cursor object',
    });

    expect(validateMessage({type: 'list_sessions', before: {sessionId: 's1'}})).toEqual({
      valid: false,
      error: 'cursor updatedAt must be a finite date string or number',
    });

    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}})).toEqual({
      valid: false,
      error: 'cursor updatedAt must be a finite date string or number',
    });

    expect(validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}})).toEqual({
      valid: false,
      error: 'cursor sessionId must be between 1 and 128 characters',
    });

    expect(validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}})).toEqual({
      valid: false,
      error: 'cursor sessionId must be between 1 and 128 characters',
    });
  });

  it('accepts user_message and returns the frame the exported union describes', () => {

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: Record<string, unknown> = { type: 'list_sessions' };

  if ('limit' in message) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'limit must be a non-negative integer'};
    }
    result.limit = message.limit;
  }

  if ('before' in message) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'before must be a cursor object'};
    }

    const before = message.before as Record<string, unknown>;

    const isFiniteDate = (val: unknown): boolean => {
      if (typeof val === 'number') return Number.isFinite(val);
      if (typeof val === 'string') {
        const time = Date.parse(val);
        return Number.isFinite(time);
      }
      return false;
    };

    if (!isFiniteDate(before.updatedAt)) {
      return {valid: false, error: 'cursor updatedAt must be a finite date string or number'};
    }

    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'cursor sessionId must be between 1 and 128 characters'};
    }

    result.before = {
      updatedAt: before.updatedAt,
      sessionId: before.sessionId,
    };
  }

  return {
    valid: true,
    data: result as unknown as IncomingMessage,
  };
}

